output_text:
[
  {
    "id": "use_cart_bay",
    "text": "Shoppers must obtain a cart from the designated cart bay before doing the trip.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "takeCartFromBay": {
          "pre": {
            "and": [
              "cartBay",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartFromBay"
    }
  },
  {
    "id": "cart_required_on_public_floor",
    "text": "Away from the cart bay and the narrow shelf aisles, shoppers should not roam without their cart.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartStagingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedOnFootZone": {
          "or": [
            "cartBay",
            "singleFileShelfAisle",
            "cartStagingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedOnFootZone"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts are forbidden in the single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_into_upper_shelf_aisle",
    "text": "At the mouth of an upper single-file shelf aisle, shoppers must not push the cart north into the aisle.",
    "abstraction": {
      "state_properties": {
        "cartStagingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "upperAisleEntrance": {
          "and": [
            "cartStagingMouth",
            "wideCrossAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "upperAisleEntrance",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "upper_shelf_items_on_foot",
    "text": "Items located in single-file shelf aisles must be taken while not holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_wide_cross_aisle",
    "text": "If a shopper leaves the cart behind, it should only be parked in a wide cross-aisle rather than in a narrow aisle or bottleneck.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "After parking a cart to enter a narrow shelf aisle, the shopper must reclaim the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "cartStagingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtStagingMouth": {
          "pre": {
            "and": [
              "cartStagingMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaimCart": {
          "pre": {
            "and": [
              "cartStagingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtStagingMouth",
      "discharge": "reclaimCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "Shoppers must leave the store with their cart rather than abandoning it inside.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
